package com.cvns.config;import org.springframework.context.annotation.*;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.*;import io.swagger.v3.oas.models.security.*;
@Configuration public class OpenApiConfig{@Bean OpenAPI api(){return new OpenAPI().info(new Info().title("Child Vaccination Notifier API").version("1.0")).addSecurityItem(new SecurityRequirement().addList("bearerAuth")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));}}
